{
  "name": "opencode-motion-video-director",
  "version": "0.1.0",
  "description": "Plan, direct, and produce code-drawn 2D/3D motion graphics and edited videos locally with OpenCode. Installs the motion-video-director skill plus a /mvd-setup preflight command and optional MCP auto-configuration.",
  "type": "module",
  "main": "./src/index.ts",
  "exports": {
    ".": "./src/index.ts"
  },
  "files": [
    "src",
    "skill"
  ],
  "scripts": {
    "test": "bun test",
    "check": "bunx tsc --noEmit",
    "build:catalog": "node scripts/build-catalog.mjs"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-skill",
    "video",
    "motion-graphics",
    "animation",
    "ffmpeg",
    "agent-skills"
  ],
  "license": "MIT",
  "author": "Viktor Arsovski",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ViksaaSkool/opencode-motion-video-director.git"
  },
  "bugs": {
    "url": "https://github.com/ViksaaSkool/opencode-motion-video-director/issues"
  },
  "homepage": "https://github.com/ViksaaSkool/opencode-motion-video-director#readme",
  "dependencies": {
    "@opencode/plugin": "latest"
  },
  "devDependencies": {
    "@types/bun": "latest",
    "typescript": "latest"
  }
}
